insert into public.categories (slug,name,name_ar,kicker,kicker_ar,description,description_ar,image_url,color,notes,sort) values ('raisins','Raisins','زبيب أفغانستان','Dried grapes','العنب المجفف','Led by the world-famous raisins of Kandahar, and sourced from other fine growing regions across Afghanistan.','يتصدرها زبيب قندهار المشهور عالمياً، إلى جانب أصناف من مناطق زراعة أخرى في أنحاء أفغانستان.','/products/about-raisins.jpg','#c99a2e','[{"title":"Grades, qualities & types","title_ar":"الدرجات والجودات والأنواع","body":"Our raisins come in a wide range of grades, qualities and types, each selected and prepared to match the preferences of our buyers.","body_ar":"يتوفر زبيبنا بمجموعة واسعة من الدرجات والجودات والأنواع، ويُنتقى ويُجهَّز كلٌّ منها بما يلائم رغبات المشترين."}]'::jsonb,0)
