insert into public.categories (slug,name,name_ar,kicker,kicker_ar,description,description_ar,image_url,color,notes,sort) values ('dried-fruits','Dried Fruits','الفواكه المجففة','Apricots · Figs · Mulberries','المشمش · التين · التوت','Naturally sun-dried in the Afghan sun, with no compromise on taste.','مجففة طبيعياً تحت الشمس الأفغانية، دون أي تنازل عن الطعم.','/products/golden-apricots.jpg','#e07b1f','[{"title":"Figs: grades, qualities & types","title_ar":"التين: الدرجات والجودات والأنواع","body":"Our figs are available in various grades, qualities and types, chosen to suit the taste and requirements of each buyer.","body_ar":"يتوفر تيننا بدرجات وجودات وأنواع متعددة، تُختار بما يناسب ذوق كل مشترٍ ومتطلباته."}]'::jsonb,1)
