insert into public.categories (slug,name,name_ar,kicker,kicker_ar,description,description_ar,image_url,color,notes,sort) values ('saffron','Saffron','الزعفران','Herat · Red gold','هرات · الذهب الأحمر','Grade A+, 100% handpicked saffron threads from Herat, known worldwide as red gold.','زعفران من الدرجة +A مقطوف يدوياً بنسبة 100% من هرات، يُعرف عالمياً بالذهب الأحمر.','/products/saffron-front.jpg','#b3261e','[{"title":"Handpicked Herati Saffron","title_ar":"زعفران هرات المقطوف يدوياً","body":"Saffron is the dried stigma of the saffron crocus, picked by hand, flower by flower. Prized worldwide as “red gold”, it gives dishes a golden colour, a rich aroma and a distinctive flavour. Our Herati saffron is hand-picked on family farms and offered as Grade A+, ideal for rice dishes, desserts, tea and drinks.","body_ar":"الزعفران هو المياسم المجففة لزهرة الزعفران، تُقطف يدوياً زهرةً بعد زهرة. ويُعرف عالمياً بـ«الذهب الأحمر»، إذ يمنح الأطباق لوناً ذهبياً وعطراً غنياً ونكهة مميزة. زعفران هرات لدينا مقطوف يدوياً من مزارع عائلية ويُقدَّم بدرجة +A، مثالي لأطباق الأرز والحلويات والشاي والمشروبات."}]'::jsonb,3)
on conflict (slug) do update set name=excluded.name,name_ar=excluded.name_ar,kicker=excluded.kicker,kicker_ar=excluded.kicker_ar,description=excluded.description,description_ar=excluded.description_ar,image_url=excluded.image_url,color=excluded.color,notes=excluded.notes,sort=excluded.sort;
insert into public.categories (slug,name,name_ar,kicker,kicker_ar,description,description_ar,image_url,color,notes,sort) values ('honey','Mountain Honey','العسل الجبلي','Badakhshan & Takhar','بدخشان وتخار','Pure honey from the high mountain meadows of Badakhshan and Takhar, far from industrial farming.','عسل صافٍ من المروج الجبلية العالية في بدخشان وتخار، بعيداً عن الزراعة الصناعية.','/products/honey-amber.jpg','#d08a12','[{"title":"Pure, naturally harvested","title_ar":"صافٍ ويُحصد طبيعياً","body":"Honey gathered from the high mountain meadows of Badakhshan and Takhar: thick, aromatic and naturally harvested, with the character of the wild alpine flowers on which the bees feed.","body_ar":"عسل يُجنى من المروج الجبلية العالية في بدخشان وتخار: كثيف القوام وعطري ويُحصد طبيعياً، يحمل طابع أزهار الجبال البرية التي يتغذى عليها النحل."},{"title":"Why Badakhshan & Takhar?","title_ar":"لماذا بدخشان وتخار؟","body":"Badakhshan and Takhar, in north-eastern Afghanistan, are among the most remote and unspoiled mountain regions in the world. Their high-altitude pastures and clean mountain air give the honey a distinctive character that buyers around the world look for.","body_ar":"تُعدّ بدخشان وتخار في شمال شرق أفغانستان من أكثر المناطق الجبلية عزلةً وبكارةً في العالم، وتمنح مراعيها المرتفعة وهواؤها الجبلي النقي العسلَ طابعاً مميزاً يبحث عنه المشترون حول العالم."}]'::jsonb,4)
on conflict (slug) do update set name=excluded.name,name_ar=excluded.name_ar,kicker=excluded.kicker,kicker_ar=excluded.kicker_ar,description=excluded.description,description_ar=excluded.description_ar,image_url=excluded.image_url,color=excluded.color,notes=excluded.notes,sort=excluded.sort;
insert into public.categories (slug,name,name_ar,kicker,kicker_ar,description,description_ar,image_url,color,notes,sort) values ('shilajit','Shilajit','الشيلاجيت','Mountain resin','راتنج الجبال','Pure Shilajit of Badakhshan, known locally as Mumiyai.','شيلاجيت بدخشان الصافي، المعروف محلياً باسم «موميايي».','/products/shilajit.jpg','#2a2420','[{"title":"What is Shilajit?","title_ar":"ما هو الشيلاجيت؟","body":"Shilajit is a natural, tar-like substance that seeps from rock crevices in high mountain ranges such as the Himalayas, Hindu Kush, Pamir and Altai. It forms slowly, over centuries, from compressed plant matter and minerals, and is rich in humic and fulvic substances and trace minerals. Known as mumijo or mumiyai in Central Asia and Afghanistan, it has been used in traditional medicine for generations, including Ayurveda.","body_ar":"الشيلاجيت مادة طبيعية لزجة تشبه القار، تتسرّب من شقوق الصخور في سلاسل الجبال العالية مثل الهيمالايا والهندوكوش والبامير وألتاي. تتكوّن ببطء على مدى قرون من بقايا النباتات والمعادن المتراكمة، وهي غنية بالأحماض الدبالية (الهيوميك والفولفيك) والمعادن الدقيقة. ويُعرف في آسيا الوسطى وأفغانستان باسم «موميو» أو «موميايي»، وقد استُخدم في الطب التقليدي منذ أجيال، ومنه الطب الأيورفيدي."},{"title":"Shilajit of Badakhshan","title_ar":"شيلاجيت بدخشان","body":"Badakhshan, in the Hindu Kush of north-eastern Afghanistan, is a traditional source of Shilajit, collected by local people from high, rocky mountain slopes. Our Badakhshan Shilajit is offered pure and carefully handled, valued for its deep black colour and dense, firm consistency.","body_ar":"تُعدّ بدخشان في جبال الهندوكوش شمال شرق أفغانستان مصدراً تقليدياً للشيلاجيت، يجمعه أهل المنطقة من سفوح الجبال الصخرية العالية. ويُقدَّم شيلاجيت بدخشان لدينا نقياً ومُعالَجاً بعناية، ويُقدَّر للونه الأسود الداكن وقوامه الكثيف المتماسك."}]'::jsonb,5)
