insert into public.products (slug,name,name_ar,description,description_ar,origin,origin_ar,unit,price_cents,compare_at_cents,category_id,image_url,gallery,art_kind,color,stock,featured) values ('herati-saffron','Herati Saffron, Grade A+','زعفران هرات درجة +A','Grade A+, 100% handpicked saffron threads from Herat, known worldwide as red gold. Ideal for rice dishes, desserts, tea and drinks.','زعفران من الدرجة +A مقطوف يدوياً بنسبة 100% من هرات، يُعرف عالمياً بالذهب الأحمر. مثالي لأطباق الأرز والحلويات والشاي والمشروبات.','Herat, Afghanistan','هرات، أفغانستان','1 g',1290,null,(select id from public.categories where slug='saffron'),'/products/herati-saffron-1.jpg',array['/products/herati-saffron-1.jpg','/products/herati-saffron-2.jpg','/products/saffron-front.jpg','/products/saffron-back.jpg']::text[],'bag','#b3261e',150,true)
