insert into public.products (slug,name,name_ar,description,description_ar,origin,origin_ar,unit,price_cents,compare_at_cents,category_id,image_url,gallery,art_kind,color,stock,featured) values ('badakhshan-mountain-honey','Mountain Honey','العسل الجبلي','Pure honey from the high mountain meadows of Badakhshan and Takhar: thick, aromatic and naturally harvested. Colour, aroma and texture vary naturally with the season and the flowers of each harvest.','عسل صافٍ من المروج الجبلية العالية في بدخشان وتخار: كثيف وعطري ويُحصد طبيعياً. يختلف لون العسل وعطره وقوامه طبيعياً باختلاف الموسم وأزهار كل موسم حصاد.','Badakhshan & Takhar','بدخشان وتخار','1 kg jar',3490,null,(select id from public.categories where slug='honey'),'/products/honey-amber.jpg',array['/products/honey-amber.jpg','/products/honey-golden.jpg','/products/honey-dark.jpg']::text[],'bag','#d08a12',30,true)
